#!/usr/bin/env node
/**
 * Renders README.md → README.html: a self-contained, styled document that
 * opens in any browser with zero dependencies, for reading the end-to-end
 * guide outside an editor. Regenerated by `npm run configure`.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { repoRoot } from './lib/course.mjs';
import { renderMarkdown } from './lib/markdown.mjs';

const md = readFileSync(path.join(repoRoot, 'README.md'), 'utf8');
const body = await renderMarkdown(md);

const css = `
  body { margin: 0 auto; max-width: 50rem; padding: 2rem 1rem 4rem; font-family: system-ui, sans-serif; line-height: 1.65; color: #1a202c; }
  @media (prefers-color-scheme: dark) { body { background: #0f1420; color: #e8edf4; } a { color: #7ca6ff; } pre, code { background: #1b2333 !important; } th { background: #171e2e !important; } td, th { border-color: #2a3548 !important; } }
  pre { background: #f1f5f9; padding: 1rem; border-radius: 8px; overflow-x: auto; }
  code { background: #f1f5f9; padding: 0.1em 0.3em; border-radius: 4px; font-size: 0.92em; }
  pre code { background: none; padding: 0; }
  table { border-collapse: collapse; width: 100%; } th, td { border: 1px solid #cbd5e1; padding: 0.4rem 0.6rem; text-align: left; } th { background: #f6f7f9; }
  h1, h2 { line-height: 1.25; } h2 { border-bottom: 1px solid #cbd5e1; padding-bottom: 0.25rem; margin-top: 2.2rem; }
`;

writeFileSync(
  path.join(repoRoot, 'README.html'),
  `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>365 Days of AI — repository guide</title><style>${css}</style></head><body>\n${body}\n</body></html>\n`,
);
console.log('✓ README.html regenerated from README.md');
